window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0a318a0e65a6cb47"]={"versions": [{"id": "FIG-0a318a0e65a6cb47", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Layered Architecture / Flow-Overlay Diagram (AUTOSAR Classic BSW-Schichtenarchitektur mit überlagertem Fehlersignalisierungs-, Polling-, Notifikations- und Recovery-Pfad).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Informations- und Kontrollflusses bei Erkennung und Behebung von Konsistenzfehlern in der Flash EEPROM Emulation (<code>Fee</code>) gemäß <code>AUTOSAR_EXP_ErrorDescription</code> (Release R4.0.3). Das Diagramm definiert die vertikale und horizontale Fehlerpropagierung vom Erkennungsort im Hardware-Abstraktions-Layer über den Speicher-Service (<code>NvM</code>) bis zur Applikation (<code>SWC</code>) und zum Diagnosespeicher (<code>Dem</code>) sowie den anschließenden Wiederherstellungspfad (<em>Recovery</em>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & BSW-Module</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer / SWCs:</strong> Empfänger von Fehlerbenachrichtigungen; optionaler Initiator von Rückfallebenen (z. B. Bereitstellung von Default-Werten).</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Entkopplungsebene; transportiert Callbacks und Service-Aufrufe zwischen NvM und SWCs (Ports: <code>NvM_NotifyJobFinished</code>, Service-Ports).</li>\n<li><strong>Services Layer:</strong></li>\n<li><strong>Memory Services (<code>NvM</code> – NVRAM Manager):</strong> Zentraler Koordinator asynchroner Speicheraufträge, Datenkonsistenzprüfung (CRC) und Fehlerbewertung. Agiert als primärer <em>Recovery Initiator</em>.</li>\n<li><strong>System Services (<code>Dem</code>, <code>DET</code>, <code>FIM</code>):</strong> <code>Dem</code> nimmt Fehlermeldungen zur Fehlerfilterung und DTC-Speicherung entgegen (<code>Dem_SetEventStatus</code>). <code>DET</code> (Development Error Tracer) für API-/Konfigurationsfehler; <code>FIM</code> (Function Inhibition Manager) zur Deaktivierung funktionaler Umfänge bei defektem Flash-Block.</li>\n<li><strong>Memory Hardware Abstraction Layer:</strong></li>\n<li><strong><code>MemIf</code> (Memory Abstraction Interface):</strong> Abstrahiert hardwarenahe Speichertreiber (<code>Fee</code> / <code>Ea</code>) und stellt eine einheitliche, indexbasierte Treiberschnittstelle bereit (<code>MemIf_GetJobResult</code>, <code>MemIf_Read</code>, <code>MemIf_Write</code>).</li>\n<li><strong><code>Fee</code> (Flash EEPROM Emulation):</strong> <em>Detection Point (1)</em>. Emuliert EEPROM-Verhalten auf sektorbasiertem Flash. Erkennt Inkonsistenzen in Block-Headern, Pointern, Statusfeldern oder Datenprüfsummen.</li>\n<li><strong><code>Ea</code> & <code>Ext. EEPROM Driver</code> / <code>Ext. Flash Driver</code>:</strong> Alternative/parallele Pfade für SPI-angebundenen externen Speicher (in diesem Szenario nicht im aktiven Signalpfad).</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL / Memory Drivers):</strong></li>\n<li><strong><code>Int. Flash Driver</code> (<code>Fls</code>):</strong> Physischer Zugriff auf den internen Flash-Controller (Erase, Write, Read). Führt hardwarenahe Recovery-Befehle aus.</li>\n<li><strong><code>SPI Handler Driver</code> & <code>Int. EEPROM Driver</code>:</strong> Alternative Hardware-Treiber.</li>\n<li><strong>Hardware-Ebene:</strong> Mikrocontroller (<code>µC</code> mit Flash, RAM-Test, interner Peripherie) und externes Flash/EEPROM.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungs- und Schnittstellen-Semantik</p>\n<ul class=\"fig-list\">\n<li><strong>Stereotypen / Semantik:</strong> Synchroner Aufruf / Polling (blau), asynchrone Callback-Benachrichtigung (rot), Fehlererkennungspunkt (roter Marker), Einleitung der Fehlerbehebung (grüner Marker), Ausführung der Fehlerbehebung (grüner Pfeil).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Erkennung – Step (1) [Detection]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Fee</code> führt während der Initialisierung (<code>Fee_Init</code>), beim Sektorwechsel oder bei einer Lese-/Schreiboperation (<code>Fee_Read</code>, <code>Fee_Write</code>) Konsistenzprüfungen durch (Überprüfung von Header-Gültigkeit, Block-Validierung, logischen Adressen).</li>\n<li>Ein inkonsistenter Zustand (z. B. unvollständiger Schreibzyklus, korrupter Marker) wird innerhalb der <code>Fee</code> detektiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Statusabfrage & Notifikation – Step (2) [Polling & Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Polling:</strong> Der <code>NvM</code> pollt periodisch den Auftragsstatus über das <code>MemIf</code> (<code>MemIf_GetJobResult()</code>), welches an <code>Fee_GetJobResult()</code> delegiert.</li>\n<li><strong>Notification:</strong> Nach Abschluss des fehlerhaften Unterauftrags meldet die <code>Fee</code> das Ergebnis <code>MEMIF_BLOCK_INCONSISTENT</code> oder <code>MEMIF_JOB_FAILED</code> über <code>MemIf</code> an den <code>NvM</code> zurück (bzw. über den konfigurierten Job-Error-Callback).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerextrapolierung & Diagnose – Step (3) [Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Horizontale Notifikation:</strong> Der <code>NvM</code> meldet das Ereignis an das <code>Dem</code> via <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> (z. B. Event <code>NVM_E_REQ_FAILED</code> oder blockspezifisches Diagnose-Event).</li>\n<li><strong>Vertikale Notifikation:</strong> Der <code>NvM</code> benachrichtigt die Applikationsschicht über die RTE via Block-Callback (<code>NvM_SingleBlockCallbackFunction</code>) oder Port-Aufruf über den fehlgeschlagenen Blockzugriff.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiederherstellungseinleitung – Step (4) [Recovery Initiator]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>NvM</code> agiert als <em>Recovery Initiator</em>:</li>\n<li><strong>Automatische NvM-Recovery:</strong> Wenn <code>NvMBlockUseCrc</code> oder Redundanz (<code>NVM_BLOCK_REDUNDANT</code>) konfiguriert ist, wird auf die redundante Kopie zugegriffen oder ROM-Default-Daten (<code>NvMRomBlockNum</code> / <code>NvMRomBlockDataAddress</code>) werden in den RAM-Mirror geladen.</li>\n<li><strong>Physischer Recovery-Pfad:</strong> Der <code>NvM</code> triggert einen Schreib-/Reparaturauftrag über <code>MemIf</code> und <code>Fee</code> an den <code>Int. Flash Driver</code> (<code>Fls</code>), um den Block neu zu allozieren, verwaiste Sektoren zu bereinigen oder Defaults persistent einzubrennen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikationsgesteuerte Wiederherstellung – Step (5) [Polling / Command]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Alternativ oder ergänzend reagiert die Applikation auf die Notifikation aus Schritt (3) und fordert explizit eine Wiederherstellung an (z. B. via <code>NvM_RestoreBlockDefaults()</code> oder explizites <code>NvM_WriteBlock()</code> mit synthetisierten Ersatzwerten über die RTE).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>NvM-Konfiguration (<code>NvMBlockDescriptor</code>):</strong></li>\n<li>Für kritische Blöcke ist <code>NvMBlockManagementType = NVM_BLOCK_REDUNDANT</code> vorzusehen, damit der <code>NvM</code> bei Konsistenzfehlern der <code>Fee</code> transparent auf Kopie 2 umschalten kann, bevor ein <code>DEM</code>-Fehler verriegelt wird.</li>\n<li><code>NvMRomBlockDataAddress</code> / <code>NvMRomBlockNum</code> konfigurieren, um deterministisches Laden von Defaultwerten bei <code>MEMIF_BLOCK_INCONSISTENT</code> ohne Blockieren der Applikation sicherzustellen.</li>\n<li>Zuweisung von <code>NvMInitBlockCallback</code> und <code>NvMSingleBlockCallbackFunction</code> zur Benachrichtigung der SWC bei Read-All- bzw. Single-Block-Fehlern.</li>\n<li><strong>Fee/Fls-Treiberrestriktionen:</strong></li>\n<li><code>Fee</code>: Muss atomare Sektorwechsel unterstützen. Die Erkennung eines ungültigen Blocks darf nicht zu Endlosschleifen im internen Garbage-Collection-Mechanismus führen.</li>\n<li>Das Polling-Intervall des <code>NvM</code> (<code>NvM_MainFunction</code>) muss auf die Zykluszeit von <code>Fee_MainFunction</code> und <code>Fls_MainFunction</code> abgestimmt sein, um Latenzen bei der Fehlererkennung zu minimieren.</li>\n<li><strong>Dem-Integration:</strong></li>\n<li>Standardmäßig qualifiziert der <code>NvM</code> Fehler erst nach Erschöpfung konfigurierter Wiederholversuche (<code>NvMMaxNumOfReadRetries</code>). Entwickler müssen sicherstellen, dass nicht jeder transiente Flash-Lesefehler sofort zu einem verfrühten DTC-Eintrag führt.</li>\n<li><strong>ASIL- / Multicore-Kontext:</strong></li>\n<li>Liegt die aufrufende SWC in einer anderen Partition/Core als der <code>NvM</code>, muss die Notifikation über RTE-Inter-Partition-Queues abgesichert sein. Puffer für Default-Werte dürfen im Fehlerfall nicht durch asynchrones Schreiben korrumpiert werden.</li>\n</ul>"}, {"id": "FIG-aaf1860826f0e81b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Layered Architecture / Flow-Overlay Diagram (AUTOSAR Classic BSW-Schichtenarchitektur mit überlagertem Fehlersignalisierungs-, Polling-, Notifikations- und Recovery-Pfad).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Informations- und Kontrollflusses bei Erkennung und Behebung von Konsistenzfehlern in der Flash EEPROM Emulation (<code>Fee</code>) gemäß <code>AUTOSAR_EXP_ErrorDescription</code> (Release R4.0.3). Das Diagramm definiert die vertikale und horizontale Fehlerpropagierung vom Erkennungsort im Hardware-Abstraktions-Layer über den Speicher-Service (<code>NvM</code>) bis zur Applikation (<code>SWC</code>) und zum Diagnosespeicher (<code>Dem</code>) sowie den anschließenden Wiederherstellungspfad (<em>Recovery</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & BSW-Module</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer / SWCs:</strong> Empfänger von Fehlerbenachrichtigungen; optionaler Initiator von Rückfallebenen (z. B. Bereitstellung von Default-Werten).</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Entkopplungsebene; transportiert Callbacks und Service-Aufrufe zwischen NvM und SWCs (Ports: <code>NvM_NotifyJobFinished</code>, Service-Ports).</li>\n<li><strong>Services Layer:</strong></li>\n<li><strong>Memory Services (<code>NvM</code> – NVRAM Manager):</strong> Zentraler Koordinator asynchroner Speicheraufträge, Datenkonsistenzprüfung (CRC) und Fehlerbewertung. Agiert als primärer <em>Recovery Initiator</em>.</li>\n<li><strong>System Services (<code>Dem</code>, <code>DET</code>, <code>FIM</code>):</strong> <code>Dem</code> nimmt Fehlermeldungen zur Fehlerfilterung und DTC-Speicherung entgegen (<code>Dem_SetEventStatus</code>). <code>DET</code> (Development Error Tracer) für API-/Konfigurationsfehler; <code>FIM</code> (Function Inhibition Manager) zur Deaktivierung funktionaler Umfänge bei defektem Flash-Block.</li>\n<li><strong>Memory Hardware Abstraction Layer:</strong></li>\n<li><strong><code>MemIf</code> (Memory Abstraction Interface):</strong> Abstrahiert hardwarenahe Speichertreiber (<code>Fee</code> / <code>Ea</code>) und stellt eine einheitliche, indexbasierte Treiberschnittstelle bereit (<code>MemIf_GetJobResult</code>, <code>MemIf_Read</code>, <code>MemIf_Write</code>).</li>\n<li><strong><code>Fee</code> (Flash EEPROM Emulation):</strong> <em>Detection Point (1)</em>. Emuliert EEPROM-Verhalten auf sektorbasiertem Flash. Erkennt Inkonsistenzen in Block-Headern, Pointern, Statusfeldern oder Datenprüfsummen.</li>\n<li><strong><code>Ea</code> & <code>Ext. EEPROM Driver</code> / <code>Ext. Flash Driver</code>:</strong> Alternative/parallele Pfade für SPI-angebundenen externen Speicher (in diesem Szenario nicht im aktiven Signalpfad).</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL / Memory Drivers):</strong></li>\n<li><strong><code>Int. Flash Driver</code> (<code>Fls</code>):</strong> Physischer Zugriff auf den internen Flash-Controller (Erase, Write, Read). Führt hardwarenahe Recovery-Befehle aus.</li>\n<li><strong><code>SPI Handler Driver</code> & <code>Int. EEPROM Driver</code>:</strong> Alternative Hardware-Treiber.</li>\n<li><strong>Hardware-Ebene:</strong> Mikrocontroller (<code>µC</code> mit Flash, RAM-Test, interner Peripherie) und externes Flash/EEPROM.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungs- und Schnittstellen-Semantik</p>\n<ul class=\"fig-list\">\n<li><strong>Stereotypen / Semantik:</strong> Synchroner Aufruf / Polling (blau), asynchrone Callback-Benachrichtigung (rot), Fehlererkennungspunkt (roter Marker), Einleitung der Fehlerbehebung (grüner Marker), Ausführung der Fehlerbehebung (grüner Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Erkennung – Step (1) [Detection]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Fee</code> führt während der Initialisierung (<code>Fee_Init</code>), beim Sektorwechsel oder bei einer Lese-/Schreiboperation (<code>Fee_Read</code>, <code>Fee_Write</code>) Konsistenzprüfungen durch (Überprüfung von Header-Gültigkeit, Block-Validierung, logischen Adressen).</li>\n<li>Ein inkonsistenter Zustand (z. B. unvollständiger Schreibzyklus, korrupter Marker) wird innerhalb der <code>Fee</code> detektiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Statusabfrage & Notifikation – Step (2) [Polling & Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Polling:</strong> Der <code>NvM</code> pollt periodisch den Auftragsstatus über das <code>MemIf</code> (<code>MemIf_GetJobResult()</code>), welches an <code>Fee_GetJobResult()</code> delegiert.</li>\n<li><strong>Notification:</strong> Nach Abschluss des fehlerhaften Unterauftrags meldet die <code>Fee</code> das Ergebnis <code>MEMIF_BLOCK_INCONSISTENT</code> oder <code>MEMIF_JOB_FAILED</code> über <code>MemIf</code> an den <code>NvM</code> zurück (bzw. über den konfigurierten Job-Error-Callback).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerextrapolierung & Diagnose – Step (3) [Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Horizontale Notifikation:</strong> Der <code>NvM</code> meldet das Ereignis an das <code>Dem</code> via <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> (z. B. Event <code>NVM_E_REQ_FAILED</code> oder blockspezifisches Diagnose-Event).</li>\n<li><strong>Vertikale Notifikation:</strong> Der <code>NvM</code> benachrichtigt die Applikationsschicht über die RTE via Block-Callback (<code>NvM_SingleBlockCallbackFunction</code>) oder Port-Aufruf über den fehlgeschlagenen Blockzugriff.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiederherstellungseinleitung – Step (4) [Recovery Initiator]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>NvM</code> agiert als <em>Recovery Initiator</em>:</li>\n<li><strong>Automatische NvM-Recovery:</strong> Wenn <code>NvMBlockUseCrc</code> oder Redundanz (<code>NVM_BLOCK_REDUNDANT</code>) konfiguriert ist, wird auf die redundante Kopie zugegriffen oder ROM-Default-Daten (<code>NvMRomBlockNum</code> / <code>NvMRomBlockDataAddress</code>) werden in den RAM-Mirror geladen.</li>\n<li><strong>Physischer Recovery-Pfad:</strong> Der <code>NvM</code> triggert einen Schreib-/Reparaturauftrag über <code>MemIf</code> und <code>Fee</code> an den <code>Int. Flash Driver</code> (<code>Fls</code>), um den Block neu zu allozieren, verwaiste Sektoren zu bereinigen oder Defaults persistent einzubrennen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikationsgesteuerte Wiederherstellung – Step (5) [Polling / Command]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Alternativ oder ergänzend reagiert die Applikation auf die Notifikation aus Schritt (3) und fordert explizit eine Wiederherstellung an (z. B. via <code>NvM_RestoreBlockDefaults()</code> oder explizites <code>NvM_WriteBlock()</code> mit synthetisierten Ersatzwerten über die RTE).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>NvM-Konfiguration (<code>NvMBlockDescriptor</code>):</strong></li>\n<li>Für kritische Blöcke ist <code>NvMBlockManagementType = NVM_BLOCK_REDUNDANT</code> vorzusehen, damit der <code>NvM</code> bei Konsistenzfehlern der <code>Fee</code> transparent auf Kopie 2 umschalten kann, bevor ein <code>DEM</code>-Fehler verriegelt wird.</li>\n<li><code>NvMRomBlockDataAddress</code> / <code>NvMRomBlockNum</code> konfigurieren, um deterministisches Laden von Defaultwerten bei <code>MEMIF_BLOCK_INCONSISTENT</code> ohne Blockieren der Applikation sicherzustellen.</li>\n<li>Zuweisung von <code>NvMInitBlockCallback</code> und <code>NvMSingleBlockCallbackFunction</code> zur Benachrichtigung der SWC bei Read-All- bzw. Single-Block-Fehlern.</li>\n<li><strong>Fee/Fls-Treiberrestriktionen:</strong></li>\n<li><code>Fee</code>: Muss atomare Sektorwechsel unterstützen. Die Erkennung eines ungültigen Blocks darf nicht zu Endlosschleifen im internen Garbage-Collection-Mechanismus führen.</li>\n<li>Das Polling-Intervall des <code>NvM</code> (<code>NvM_MainFunction</code>) muss auf die Zykluszeit von <code>Fee_MainFunction</code> und <code>Fls_MainFunction</code> abgestimmt sein, um Latenzen bei der Fehlererkennung zu minimieren.</li>\n<li><strong>Dem-Integration:</strong></li>\n<li>Standardmäßig qualifiziert der <code>NvM</code> Fehler erst nach Erschöpfung konfigurierter Wiederholversuche (<code>NvMMaxNumOfReadRetries</code>). Entwickler müssen sicherstellen, dass nicht jeder transiente Flash-Lesefehler sofort zu einem verfrühten DTC-Eintrag führt.</li>\n<li><strong>ASIL- / Multicore-Kontext:</strong></li>\n<li>Liegt die aufrufende SWC in einer anderen Partition/Core als der <code>NvM</code>, muss die Notifikation über RTE-Inter-Partition-Queues abgesichert sein. Puffer für Default-Werte dürfen im Fehlerfall nicht durch asynchrones Schreiben korrumpiert werden.</li>\n</ul>"}, {"id": "FIG-c67ea0e6be9988a9", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Layered Architecture / Flow-Overlay Diagram (AUTOSAR Classic BSW-Schichtenarchitektur mit überlagertem Fehlersignalisierungs-, Polling-, Notifikations- und Recovery-Pfad).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Informations- und Kontrollflusses bei Erkennung und Behebung von Konsistenzfehlern in der Flash EEPROM Emulation (<code>Fee</code>) gemäß <code>AUTOSAR_EXP_ErrorDescription</code> (Release R4.0.3). Das Diagramm definiert die vertikale und horizontale Fehlerpropagierung vom Erkennungsort im Hardware-Abstraktions-Layer über den Speicher-Service (<code>NvM</code>) bis zur Applikation (<code>SWC</code>) und zum Diagnosespeicher (<code>Dem</code>) sowie den anschließenden Wiederherstellungspfad (<em>Recovery</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & BSW-Module</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer / SWCs:</strong> Empfänger von Fehlerbenachrichtigungen; optionaler Initiator von Rückfallebenen (z. B. Bereitstellung von Default-Werten).</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Entkopplungsebene; transportiert Callbacks und Service-Aufrufe zwischen NvM und SWCs (Ports: <code>NvM_NotifyJobFinished</code>, Service-Ports).</li>\n<li><strong>Services Layer:</strong></li>\n<li><strong>Memory Services (<code>NvM</code> – NVRAM Manager):</strong> Zentraler Koordinator asynchroner Speicheraufträge, Datenkonsistenzprüfung (CRC) und Fehlerbewertung. Agiert als primärer <em>Recovery Initiator</em>.</li>\n<li><strong>System Services (<code>Dem</code>, <code>DET</code>, <code>FIM</code>):</strong> <code>Dem</code> nimmt Fehlermeldungen zur Fehlerfilterung und DTC-Speicherung entgegen (<code>Dem_SetEventStatus</code>). <code>DET</code> (Development Error Tracer) für API-/Konfigurationsfehler; <code>FIM</code> (Function Inhibition Manager) zur Deaktivierung funktionaler Umfänge bei defektem Flash-Block.</li>\n<li><strong>Memory Hardware Abstraction Layer:</strong></li>\n<li><strong><code>MemIf</code> (Memory Abstraction Interface):</strong> Abstrahiert hardwarenahe Speichertreiber (<code>Fee</code> / <code>Ea</code>) und stellt eine einheitliche, indexbasierte Treiberschnittstelle bereit (<code>MemIf_GetJobResult</code>, <code>MemIf_Read</code>, <code>MemIf_Write</code>).</li>\n<li><strong><code>Fee</code> (Flash EEPROM Emulation):</strong> <em>Detection Point (1)</em>. Emuliert EEPROM-Verhalten auf sektorbasiertem Flash. Erkennt Inkonsistenzen in Block-Headern, Pointern, Statusfeldern oder Datenprüfsummen.</li>\n<li><strong><code>Ea</code> & <code>Ext. EEPROM Driver</code> / <code>Ext. Flash Driver</code>:</strong> Alternative/parallele Pfade für SPI-angebundenen externen Speicher (in diesem Szenario nicht im aktiven Signalpfad).</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL / Memory Drivers):</strong></li>\n<li><strong><code>Int. Flash Driver</code> (<code>Fls</code>):</strong> Physischer Zugriff auf den internen Flash-Controller (Erase, Write, Read). Führt hardwarenahe Recovery-Befehle aus.</li>\n<li><strong><code>SPI Handler Driver</code> & <code>Int. EEPROM Driver</code>:</strong> Alternative Hardware-Treiber.</li>\n<li><strong>Hardware-Ebene:</strong> Mikrocontroller (<code>µC</code> mit Flash, RAM-Test, interner Peripherie) und externes Flash/EEPROM.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungs- und Schnittstellen-Semantik</p>\n<ul class=\"fig-list\">\n<li><strong>Stereotypen / Semantik:</strong> Synchroner Aufruf / Polling (blau), asynchrone Callback-Benachrichtigung (rot), Fehlererkennungspunkt (roter Marker), Einleitung der Fehlerbehebung (grüner Marker), Ausführung der Fehlerbehebung (grüner Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Erkennung – Step (1) [Detection]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Fee</code> führt während der Initialisierung (<code>Fee_Init</code>), beim Sektorwechsel oder bei einer Lese-/Schreiboperation (<code>Fee_Read</code>, <code>Fee_Write</code>) Konsistenzprüfungen durch (Überprüfung von Header-Gültigkeit, Block-Validierung, logischen Adressen).</li>\n<li>Ein inkonsistenter Zustand (z. B. unvollständiger Schreibzyklus, korrupter Marker) wird innerhalb der <code>Fee</code> detektiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Statusabfrage & Notifikation – Step (2) [Polling & Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Polling:</strong> Der <code>NvM</code> pollt periodisch den Auftragsstatus über das <code>MemIf</code> (<code>MemIf_GetJobResult()</code>), welches an <code>Fee_GetJobResult()</code> delegiert.</li>\n<li><strong>Notification:</strong> Nach Abschluss des fehlerhaften Unterauftrags meldet die <code>Fee</code> das Ergebnis <code>MEMIF_BLOCK_INCONSISTENT</code> oder <code>MEMIF_JOB_FAILED</code> über <code>MemIf</code> an den <code>NvM</code> zurück (bzw. über den konfigurierten Job-Error-Callback).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerextrapolierung & Diagnose – Step (3) [Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Horizontale Notifikation:</strong> Der <code>NvM</code> meldet das Ereignis an das <code>Dem</code> via <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> (z. B. Event <code>NVM_E_REQ_FAILED</code> oder blockspezifisches Diagnose-Event).</li>\n<li><strong>Vertikale Notifikation:</strong> Der <code>NvM</code> benachrichtigt die Applikationsschicht über die RTE via Block-Callback (<code>NvM_SingleBlockCallbackFunction</code>) oder Port-Aufruf über den fehlgeschlagenen Blockzugriff.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiederherstellungseinleitung – Step (4) [Recovery Initiator]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>NvM</code> agiert als <em>Recovery Initiator</em>:</li>\n<li><strong>Automatische NvM-Recovery:</strong> Wenn <code>NvMBlockUseCrc</code> oder Redundanz (<code>NVM_BLOCK_REDUNDANT</code>) konfiguriert ist, wird auf die redundante Kopie zugegriffen oder ROM-Default-Daten (<code>NvMRomBlockNum</code> / <code>NvMRomBlockDataAddress</code>) werden in den RAM-Mirror geladen.</li>\n<li><strong>Physischer Recovery-Pfad:</strong> Der <code>NvM</code> triggert einen Schreib-/Reparaturauftrag über <code>MemIf</code> und <code>Fee</code> an den <code>Int. Flash Driver</code> (<code>Fls</code>), um den Block neu zu allozieren, verwaiste Sektoren zu bereinigen oder Defaults persistent einzubrennen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikationsgesteuerte Wiederherstellung – Step (5) [Polling / Command]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Alternativ oder ergänzend reagiert die Applikation auf die Notifikation aus Schritt (3) und fordert explizit eine Wiederherstellung an (z. B. via <code>NvM_RestoreBlockDefaults()</code> oder explizites <code>NvM_WriteBlock()</code> mit synthetisierten Ersatzwerten über die RTE).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>NvM-Konfiguration (<code>NvMBlockDescriptor</code>):</strong></li>\n<li>Für kritische Blöcke ist <code>NvMBlockManagementType = NVM_BLOCK_REDUNDANT</code> vorzusehen, damit der <code>NvM</code> bei Konsistenzfehlern der <code>Fee</code> transparent auf Kopie 2 umschalten kann, bevor ein <code>DEM</code>-Fehler verriegelt wird.</li>\n<li><code>NvMRomBlockDataAddress</code> / <code>NvMRomBlockNum</code> konfigurieren, um deterministisches Laden von Defaultwerten bei <code>MEMIF_BLOCK_INCONSISTENT</code> ohne Blockieren der Applikation sicherzustellen.</li>\n<li>Zuweisung von <code>NvMInitBlockCallback</code> und <code>NvMSingleBlockCallbackFunction</code> zur Benachrichtigung der SWC bei Read-All- bzw. Single-Block-Fehlern.</li>\n<li><strong>Fee/Fls-Treiberrestriktionen:</strong></li>\n<li><code>Fee</code>: Muss atomare Sektorwechsel unterstützen. Die Erkennung eines ungültigen Blocks darf nicht zu Endlosschleifen im internen Garbage-Collection-Mechanismus führen.</li>\n<li>Das Polling-Intervall des <code>NvM</code> (<code>NvM_MainFunction</code>) muss auf die Zykluszeit von <code>Fee_MainFunction</code> und <code>Fls_MainFunction</code> abgestimmt sein, um Latenzen bei der Fehlererkennung zu minimieren.</li>\n<li><strong>Dem-Integration:</strong></li>\n<li>Standardmäßig qualifiziert der <code>NvM</code> Fehler erst nach Erschöpfung konfigurierter Wiederholversuche (<code>NvMMaxNumOfReadRetries</code>). Entwickler müssen sicherstellen, dass nicht jeder transiente Flash-Lesefehler sofort zu einem verfrühten DTC-Eintrag führt.</li>\n<li><strong>ASIL- / Multicore-Kontext:</strong></li>\n<li>Liegt die aufrufende SWC in einer anderen Partition/Core als der <code>NvM</code>, muss die Notifikation über RTE-Inter-Partition-Queues abgesichert sein. Puffer für Default-Werte dürfen im Fehlerfall nicht durch asynchrones Schreiben korrumpiert werden.</li>\n</ul>"}, {"id": "FIG-5d49904050010c6f", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Layered Architecture / Flow-Overlay Diagram (AUTOSAR Classic BSW-Schichtenarchitektur mit überlagertem Fehlersignalisierungs-, Polling-, Notifikations- und Recovery-Pfad).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Informations- und Kontrollflusses bei Erkennung und Behebung von Konsistenzfehlern in der Flash EEPROM Emulation (<code>Fee</code>) gemäß <code>AUTOSAR_EXP_ErrorDescription</code> (Release R4.0.3). Das Diagramm definiert die vertikale und horizontale Fehlerpropagierung vom Erkennungsort im Hardware-Abstraktions-Layer über den Speicher-Service (<code>NvM</code>) bis zur Applikation (<code>SWC</code>) und zum Diagnosespeicher (<code>Dem</code>) sowie den anschließenden Wiederherstellungspfad (<em>Recovery</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & BSW-Module</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer / SWCs:</strong> Empfänger von Fehlerbenachrichtigungen; optionaler Initiator von Rückfallebenen (z. B. Bereitstellung von Default-Werten).</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Entkopplungsebene; transportiert Callbacks und Service-Aufrufe zwischen NvM und SWCs (Ports: <code>NvM_NotifyJobFinished</code>, Service-Ports).</li>\n<li><strong>Services Layer:</strong></li>\n<li><strong>Memory Services (<code>NvM</code> – NVRAM Manager):</strong> Zentraler Koordinator asynchroner Speicheraufträge, Datenkonsistenzprüfung (CRC) und Fehlerbewertung. Agiert als primärer <em>Recovery Initiator</em>.</li>\n<li><strong>System Services (<code>Dem</code>, <code>DET</code>, <code>FIM</code>):</strong> <code>Dem</code> nimmt Fehlermeldungen zur Fehlerfilterung und DTC-Speicherung entgegen (<code>Dem_SetEventStatus</code>). <code>DET</code> (Development Error Tracer) für API-/Konfigurationsfehler; <code>FIM</code> (Function Inhibition Manager) zur Deaktivierung funktionaler Umfänge bei defektem Flash-Block.</li>\n<li><strong>Memory Hardware Abstraction Layer:</strong></li>\n<li><strong><code>MemIf</code> (Memory Abstraction Interface):</strong> Abstrahiert hardwarenahe Speichertreiber (<code>Fee</code> / <code>Ea</code>) und stellt eine einheitliche, indexbasierte Treiberschnittstelle bereit (<code>MemIf_GetJobResult</code>, <code>MemIf_Read</code>, <code>MemIf_Write</code>).</li>\n<li><strong><code>Fee</code> (Flash EEPROM Emulation):</strong> <em>Detection Point (1)</em>. Emuliert EEPROM-Verhalten auf sektorbasiertem Flash. Erkennt Inkonsistenzen in Block-Headern, Pointern, Statusfeldern oder Datenprüfsummen.</li>\n<li><strong><code>Ea</code> & <code>Ext. EEPROM Driver</code> / <code>Ext. Flash Driver</code>:</strong> Alternative/parallele Pfade für SPI-angebundenen externen Speicher (in diesem Szenario nicht im aktiven Signalpfad).</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL / Memory Drivers):</strong></li>\n<li><strong><code>Int. Flash Driver</code> (<code>Fls</code>):</strong> Physischer Zugriff auf den internen Flash-Controller (Erase, Write, Read). Führt hardwarenahe Recovery-Befehle aus.</li>\n<li><strong><code>SPI Handler Driver</code> & <code>Int. EEPROM Driver</code>:</strong> Alternative Hardware-Treiber.</li>\n<li><strong>Hardware-Ebene:</strong> Mikrocontroller (<code>µC</code> mit Flash, RAM-Test, interner Peripherie) und externes Flash/EEPROM.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungs- und Schnittstellen-Semantik</p>\n<ul class=\"fig-list\">\n<li><strong>Stereotypen / Semantik:</strong> Synchroner Aufruf / Polling (blau), asynchrone Callback-Benachrichtigung (rot), Fehlererkennungspunkt (roter Marker), Einleitung der Fehlerbehebung (grüner Marker), Ausführung der Fehlerbehebung (grüner Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Erkennung – Step (1) [Detection]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Fee</code> führt während der Initialisierung (<code>Fee_Init</code>), beim Sektorwechsel oder bei einer Lese-/Schreiboperation (<code>Fee_Read</code>, <code>Fee_Write</code>) Konsistenzprüfungen durch (Überprüfung von Header-Gültigkeit, Block-Validierung, logischen Adressen).</li>\n<li>Ein inkonsistenter Zustand (z. B. unvollständiger Schreibzyklus, korrupter Marker) wird innerhalb der <code>Fee</code> detektiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Statusabfrage & Notifikation – Step (2) [Polling & Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Polling:</strong> Der <code>NvM</code> pollt periodisch den Auftragsstatus über das <code>MemIf</code> (<code>MemIf_GetJobResult()</code>), welches an <code>Fee_GetJobResult()</code> delegiert.</li>\n<li><strong>Notification:</strong> Nach Abschluss des fehlerhaften Unterauftrags meldet die <code>Fee</code> das Ergebnis <code>MEMIF_BLOCK_INCONSISTENT</code> oder <code>MEMIF_JOB_FAILED</code> über <code>MemIf</code> an den <code>NvM</code> zurück (bzw. über den konfigurierten Job-Error-Callback).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerextrapolierung & Diagnose – Step (3) [Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Horizontale Notifikation:</strong> Der <code>NvM</code> meldet das Ereignis an das <code>Dem</code> via <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> (z. B. Event <code>NVM_E_REQ_FAILED</code> oder blockspezifisches Diagnose-Event).</li>\n<li><strong>Vertikale Notifikation:</strong> Der <code>NvM</code> benachrichtigt die Applikationsschicht über die RTE via Block-Callback (<code>NvM_SingleBlockCallbackFunction</code>) oder Port-Aufruf über den fehlgeschlagenen Blockzugriff.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiederherstellungseinleitung – Step (4) [Recovery Initiator]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>NvM</code> agiert als <em>Recovery Initiator</em>:</li>\n<li><strong>Automatische NvM-Recovery:</strong> Wenn <code>NvMBlockUseCrc</code> oder Redundanz (<code>NVM_BLOCK_REDUNDANT</code>) konfiguriert ist, wird auf die redundante Kopie zugegriffen oder ROM-Default-Daten (<code>NvMRomBlockNum</code> / <code>NvMRomBlockDataAddress</code>) werden in den RAM-Mirror geladen.</li>\n<li><strong>Physischer Recovery-Pfad:</strong> Der <code>NvM</code> triggert einen Schreib-/Reparaturauftrag über <code>MemIf</code> und <code>Fee</code> an den <code>Int. Flash Driver</code> (<code>Fls</code>), um den Block neu zu allozieren, verwaiste Sektoren zu bereinigen oder Defaults persistent einzubrennen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikationsgesteuerte Wiederherstellung – Step (5) [Polling / Command]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Alternativ oder ergänzend reagiert die Applikation auf die Notifikation aus Schritt (3) und fordert explizit eine Wiederherstellung an (z. B. via <code>NvM_RestoreBlockDefaults()</code> oder explizites <code>NvM_WriteBlock()</code> mit synthetisierten Ersatzwerten über die RTE).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>NvM-Konfiguration (<code>NvMBlockDescriptor</code>):</strong></li>\n<li>Für kritische Blöcke ist <code>NvMBlockManagementType = NVM_BLOCK_REDUNDANT</code> vorzusehen, damit der <code>NvM</code> bei Konsistenzfehlern der <code>Fee</code> transparent auf Kopie 2 umschalten kann, bevor ein <code>DEM</code>-Fehler verriegelt wird.</li>\n<li><code>NvMRomBlockDataAddress</code> / <code>NvMRomBlockNum</code> konfigurieren, um deterministisches Laden von Defaultwerten bei <code>MEMIF_BLOCK_INCONSISTENT</code> ohne Blockieren der Applikation sicherzustellen.</li>\n<li>Zuweisung von <code>NvMInitBlockCallback</code> und <code>NvMSingleBlockCallbackFunction</code> zur Benachrichtigung der SWC bei Read-All- bzw. Single-Block-Fehlern.</li>\n<li><strong>Fee/Fls-Treiberrestriktionen:</strong></li>\n<li><code>Fee</code>: Muss atomare Sektorwechsel unterstützen. Die Erkennung eines ungültigen Blocks darf nicht zu Endlosschleifen im internen Garbage-Collection-Mechanismus führen.</li>\n<li>Das Polling-Intervall des <code>NvM</code> (<code>NvM_MainFunction</code>) muss auf die Zykluszeit von <code>Fee_MainFunction</code> und <code>Fls_MainFunction</code> abgestimmt sein, um Latenzen bei der Fehlererkennung zu minimieren.</li>\n<li><strong>Dem-Integration:</strong></li>\n<li>Standardmäßig qualifiziert der <code>NvM</code> Fehler erst nach Erschöpfung konfigurierter Wiederholversuche (<code>NvMMaxNumOfReadRetries</code>). Entwickler müssen sicherstellen, dass nicht jeder transiente Flash-Lesefehler sofort zu einem verfrühten DTC-Eintrag führt.</li>\n<li><strong>ASIL- / Multicore-Kontext:</strong></li>\n<li>Liegt die aufrufende SWC in einer anderen Partition/Core als der <code>NvM</code>, muss die Notifikation über RTE-Inter-Partition-Queues abgesichert sein. Puffer für Default-Werte dürfen im Fehlerfall nicht durch asynchrones Schreiben korrumpiert werden.</li>\n</ul>"}, {"id": "FIG-bfcf7b5cc8f0468a", "releases": ["R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Layered Architecture / Flow-Overlay Diagram (AUTOSAR Classic BSW-Schichtenarchitektur mit überlagertem Fehlersignalisierungs-, Polling-, Notifikations- und Recovery-Pfad).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Informations- und Kontrollflusses bei Erkennung und Behebung von Konsistenzfehlern in der Flash EEPROM Emulation (<code>Fee</code>) gemäß <code>AUTOSAR_EXP_ErrorDescription</code> (Release R4.0.3). Das Diagramm definiert die vertikale und horizontale Fehlerpropagierung vom Erkennungsort im Hardware-Abstraktions-Layer über den Speicher-Service (<code>NvM</code>) bis zur Applikation (<code>SWC</code>) und zum Diagnosespeicher (<code>Dem</code>) sowie den anschließenden Wiederherstellungspfad (<em>Recovery</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & BSW-Module</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer / SWCs:</strong> Empfänger von Fehlerbenachrichtigungen; optionaler Initiator von Rückfallebenen (z. B. Bereitstellung von Default-Werten).</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Entkopplungsebene; transportiert Callbacks und Service-Aufrufe zwischen NvM und SWCs (Ports: <code>NvM_NotifyJobFinished</code>, Service-Ports).</li>\n<li><strong>Services Layer:</strong></li>\n<li><strong>Memory Services (<code>NvM</code> – NVRAM Manager):</strong> Zentraler Koordinator asynchroner Speicheraufträge, Datenkonsistenzprüfung (CRC) und Fehlerbewertung. Agiert als primärer <em>Recovery Initiator</em>.</li>\n<li><strong>System Services (<code>Dem</code>, <code>DET</code>, <code>FIM</code>):</strong> <code>Dem</code> nimmt Fehlermeldungen zur Fehlerfilterung und DTC-Speicherung entgegen (<code>Dem_SetEventStatus</code>). <code>DET</code> (Development Error Tracer) für API-/Konfigurationsfehler; <code>FIM</code> (Function Inhibition Manager) zur Deaktivierung funktionaler Umfänge bei defektem Flash-Block.</li>\n<li><strong>Memory Hardware Abstraction Layer:</strong></li>\n<li><strong><code>MemIf</code> (Memory Abstraction Interface):</strong> Abstrahiert hardwarenahe Speichertreiber (<code>Fee</code> / <code>Ea</code>) und stellt eine einheitliche, indexbasierte Treiberschnittstelle bereit (<code>MemIf_GetJobResult</code>, <code>MemIf_Read</code>, <code>MemIf_Write</code>).</li>\n<li><strong><code>Fee</code> (Flash EEPROM Emulation):</strong> <em>Detection Point (1)</em>. Emuliert EEPROM-Verhalten auf sektorbasiertem Flash. Erkennt Inkonsistenzen in Block-Headern, Pointern, Statusfeldern oder Datenprüfsummen.</li>\n<li><strong><code>Ea</code> & <code>Ext. EEPROM Driver</code> / <code>Ext. Flash Driver</code>:</strong> Alternative/parallele Pfade für SPI-angebundenen externen Speicher (in diesem Szenario nicht im aktiven Signalpfad).</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL / Memory Drivers):</strong></li>\n<li><strong><code>Int. Flash Driver</code> (<code>Fls</code>):</strong> Physischer Zugriff auf den internen Flash-Controller (Erase, Write, Read). Führt hardwarenahe Recovery-Befehle aus.</li>\n<li><strong><code>SPI Handler Driver</code> & <code>Int. EEPROM Driver</code>:</strong> Alternative Hardware-Treiber.</li>\n<li><strong>Hardware-Ebene:</strong> Mikrocontroller (<code>µC</code> mit Flash, RAM-Test, interner Peripherie) und externes Flash/EEPROM.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungs- und Schnittstellen-Semantik</p>\n<ul class=\"fig-list\">\n<li><strong>Stereotypen / Semantik:</strong> Synchroner Aufruf / Polling (blau), asynchrone Callback-Benachrichtigung (rot), Fehlererkennungspunkt (roter Marker), Einleitung der Fehlerbehebung (grüner Marker), Ausführung der Fehlerbehebung (grüner Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Erkennung – Step (1) [Detection]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Fee</code> führt während der Initialisierung (<code>Fee_Init</code>), beim Sektorwechsel oder bei einer Lese-/Schreiboperation (<code>Fee_Read</code>, <code>Fee_Write</code>) Konsistenzprüfungen durch (Überprüfung von Header-Gültigkeit, Block-Validierung, logischen Adressen).</li>\n<li>Ein inkonsistenter Zustand (z. B. unvollständiger Schreibzyklus, korrupter Marker) wird innerhalb der <code>Fee</code> detektiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Statusabfrage & Notifikation – Step (2) [Polling & Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Polling:</strong> Der <code>NvM</code> pollt periodisch den Auftragsstatus über das <code>MemIf</code> (<code>MemIf_GetJobResult()</code>), welches an <code>Fee_GetJobResult()</code> delegiert.</li>\n<li><strong>Notification:</strong> Nach Abschluss des fehlerhaften Unterauftrags meldet die <code>Fee</code> das Ergebnis <code>MEMIF_BLOCK_INCONSISTENT</code> oder <code>MEMIF_JOB_FAILED</code> über <code>MemIf</code> an den <code>NvM</code> zurück (bzw. über den konfigurierten Job-Error-Callback).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerextrapolierung & Diagnose – Step (3) [Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Horizontale Notifikation:</strong> Der <code>NvM</code> meldet das Ereignis an das <code>Dem</code> via <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> (z. B. Event <code>NVM_E_REQ_FAILED</code> oder blockspezifisches Diagnose-Event).</li>\n<li><strong>Vertikale Notifikation:</strong> Der <code>NvM</code> benachrichtigt die Applikationsschicht über die RTE via Block-Callback (<code>NvM_SingleBlockCallbackFunction</code>) oder Port-Aufruf über den fehlgeschlagenen Blockzugriff.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiederherstellungseinleitung – Step (4) [Recovery Initiator]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>NvM</code> agiert als <em>Recovery Initiator</em>:</li>\n<li><strong>Automatische NvM-Recovery:</strong> Wenn <code>NvMBlockUseCrc</code> oder Redundanz (<code>NVM_BLOCK_REDUNDANT</code>) konfiguriert ist, wird auf die redundante Kopie zugegriffen oder ROM-Default-Daten (<code>NvMRomBlockNum</code> / <code>NvMRomBlockDataAddress</code>) werden in den RAM-Mirror geladen.</li>\n<li><strong>Physischer Recovery-Pfad:</strong> Der <code>NvM</code> triggert einen Schreib-/Reparaturauftrag über <code>MemIf</code> und <code>Fee</code> an den <code>Int. Flash Driver</code> (<code>Fls</code>), um den Block neu zu allozieren, verwaiste Sektoren zu bereinigen oder Defaults persistent einzubrennen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikationsgesteuerte Wiederherstellung – Step (5) [Polling / Command]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Alternativ oder ergänzend reagiert die Applikation auf die Notifikation aus Schritt (3) und fordert explizit eine Wiederherstellung an (z. B. via <code>NvM_RestoreBlockDefaults()</code> oder explizites <code>NvM_WriteBlock()</code> mit synthetisierten Ersatzwerten über die RTE).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>NvM-Konfiguration (<code>NvMBlockDescriptor</code>):</strong></li>\n<li>Für kritische Blöcke ist <code>NvMBlockManagementType = NVM_BLOCK_REDUNDANT</code> vorzusehen, damit der <code>NvM</code> bei Konsistenzfehlern der <code>Fee</code> transparent auf Kopie 2 umschalten kann, bevor ein <code>DEM</code>-Fehler verriegelt wird.</li>\n<li><code>NvMRomBlockDataAddress</code> / <code>NvMRomBlockNum</code> konfigurieren, um deterministisches Laden von Defaultwerten bei <code>MEMIF_BLOCK_INCONSISTENT</code> ohne Blockieren der Applikation sicherzustellen.</li>\n<li>Zuweisung von <code>NvMInitBlockCallback</code> und <code>NvMSingleBlockCallbackFunction</code> zur Benachrichtigung der SWC bei Read-All- bzw. Single-Block-Fehlern.</li>\n<li><strong>Fee/Fls-Treiberrestriktionen:</strong></li>\n<li><code>Fee</code>: Muss atomare Sektorwechsel unterstützen. Die Erkennung eines ungültigen Blocks darf nicht zu Endlosschleifen im internen Garbage-Collection-Mechanismus führen.</li>\n<li>Das Polling-Intervall des <code>NvM</code> (<code>NvM_MainFunction</code>) muss auf die Zykluszeit von <code>Fee_MainFunction</code> und <code>Fls_MainFunction</code> abgestimmt sein, um Latenzen bei der Fehlererkennung zu minimieren.</li>\n<li><strong>Dem-Integration:</strong></li>\n<li>Standardmäßig qualifiziert der <code>NvM</code> Fehler erst nach Erschöpfung konfigurierter Wiederholversuche (<code>NvMMaxNumOfReadRetries</code>). Entwickler müssen sicherstellen, dass nicht jeder transiente Flash-Lesefehler sofort zu einem verfrühten DTC-Eintrag führt.</li>\n<li><strong>ASIL- / Multicore-Kontext:</strong></li>\n<li>Liegt die aufrufende SWC in einer anderen Partition/Core als der <code>NvM</code>, muss die Notifikation über RTE-Inter-Partition-Queues abgesichert sein. Puffer für Default-Werte dürfen im Fehlerfall nicht durch asynchrones Schreiben korrumpiert werden.</li>\n</ul>"}, {"id": "FIG-d61f76a6abda6872", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Layered Architecture / Flow-Overlay Diagram (AUTOSAR Classic BSW-Schichtenarchitektur mit überlagertem Fehlersignalisierungs-, Polling-, Notifikations- und Recovery-Pfad).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Informations- und Kontrollflusses bei Erkennung und Behebung von Konsistenzfehlern in der Flash EEPROM Emulation (<code>Fee</code>) gemäß <code>AUTOSAR_EXP_ErrorDescription</code> (Release R4.0.3). Das Diagramm definiert die vertikale und horizontale Fehlerpropagierung vom Erkennungsort im Hardware-Abstraktions-Layer über den Speicher-Service (<code>NvM</code>) bis zur Applikation (<code>SWC</code>) und zum Diagnosespeicher (<code>Dem</code>) sowie den anschließenden Wiederherstellungspfad (<em>Recovery</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & BSW-Module</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer / SWCs:</strong> Empfänger von Fehlerbenachrichtigungen; optionaler Initiator von Rückfallebenen (z. B. Bereitstellung von Default-Werten).</li>\n<li><strong>AUTOSAR Runtime Environment (RTE):</strong> Entkopplungsebene; transportiert Callbacks und Service-Aufrufe zwischen NvM und SWCs (Ports: <code>NvM_NotifyJobFinished</code>, Service-Ports).</li>\n<li><strong>Services Layer:</strong></li>\n<li><strong>Memory Services (<code>NvM</code> – NVRAM Manager):</strong> Zentraler Koordinator asynchroner Speicheraufträge, Datenkonsistenzprüfung (CRC) und Fehlerbewertung. Agiert als primärer <em>Recovery Initiator</em>.</li>\n<li><strong>System Services (<code>Dem</code>, <code>DET</code>, <code>FIM</code>):</strong> <code>Dem</code> nimmt Fehlermeldungen zur Fehlerfilterung und DTC-Speicherung entgegen (<code>Dem_SetEventStatus</code>). <code>DET</code> (Development Error Tracer) für API-/Konfigurationsfehler; <code>FIM</code> (Function Inhibition Manager) zur Deaktivierung funktionaler Umfänge bei defektem Flash-Block.</li>\n<li><strong>Memory Hardware Abstraction Layer:</strong></li>\n<li><strong><code>MemIf</code> (Memory Abstraction Interface):</strong> Abstrahiert hardwarenahe Speichertreiber (<code>Fee</code> / <code>Ea</code>) und stellt eine einheitliche, indexbasierte Treiberschnittstelle bereit (<code>MemIf_GetJobResult</code>, <code>MemIf_Read</code>, <code>MemIf_Write</code>).</li>\n<li><strong><code>Fee</code> (Flash EEPROM Emulation):</strong> <em>Detection Point (1)</em>. Emuliert EEPROM-Verhalten auf sektorbasiertem Flash. Erkennt Inkonsistenzen in Block-Headern, Pointern, Statusfeldern oder Datenprüfsummen.</li>\n<li><strong><code>Ea</code> & <code>Ext. EEPROM Driver</code> / <code>Ext. Flash Driver</code>:</strong> Alternative/parallele Pfade für SPI-angebundenen externen Speicher (in diesem Szenario nicht im aktiven Signalpfad).</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL / Memory Drivers):</strong></li>\n<li><strong><code>Int. Flash Driver</code> (<code>Fls</code>):</strong> Physischer Zugriff auf den internen Flash-Controller (Erase, Write, Read). Führt hardwarenahe Recovery-Befehle aus.</li>\n<li><strong><code>SPI Handler Driver</code> & <code>Int. EEPROM Driver</code>:</strong> Alternative Hardware-Treiber.</li>\n<li><strong>Hardware-Ebene:</strong> Mikrocontroller (<code>µC</code> mit Flash, RAM-Test, interner Peripherie) und externes Flash/EEPROM.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungs- und Schnittstellen-Semantik</p>\n<ul class=\"fig-list\">\n<li><strong>Stereotypen / Semantik:</strong> Synchroner Aufruf / Polling (blau), asynchrone Callback-Benachrichtigung (rot), Fehlererkennungspunkt (roter Marker), Einleitung der Fehlerbehebung (grüner Marker), Ausführung der Fehlerbehebung (grüner Pfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Erkennung – Step (1) [Detection]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <code>Fee</code> führt während der Initialisierung (<code>Fee_Init</code>), beim Sektorwechsel oder bei einer Lese-/Schreiboperation (<code>Fee_Read</code>, <code>Fee_Write</code>) Konsistenzprüfungen durch (Überprüfung von Header-Gültigkeit, Block-Validierung, logischen Adressen).</li>\n<li>Ein inkonsistenter Zustand (z. B. unvollständiger Schreibzyklus, korrupter Marker) wird innerhalb der <code>Fee</code> detektiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Statusabfrage & Notifikation – Step (2) [Polling & Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Polling:</strong> Der <code>NvM</code> pollt periodisch den Auftragsstatus über das <code>MemIf</code> (<code>MemIf_GetJobResult()</code>), welches an <code>Fee_GetJobResult()</code> delegiert.</li>\n<li><strong>Notification:</strong> Nach Abschluss des fehlerhaften Unterauftrags meldet die <code>Fee</code> das Ergebnis <code>MEMIF_BLOCK_INCONSISTENT</code> oder <code>MEMIF_JOB_FAILED</code> über <code>MemIf</code> an den <code>NvM</code> zurück (bzw. über den konfigurierten Job-Error-Callback).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerextrapolierung & Diagnose – Step (3) [Notification]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Horizontale Notifikation:</strong> Der <code>NvM</code> meldet das Ereignis an das <code>Dem</code> via <code>Dem_SetEventStatus(EventId, DEM_EVENT_STATUS_FAILED)</code> (z. B. Event <code>NVM_E_REQ_FAILED</code> oder blockspezifisches Diagnose-Event).</li>\n<li><strong>Vertikale Notifikation:</strong> Der <code>NvM</code> benachrichtigt die Applikationsschicht über die RTE via Block-Callback (<code>NvM_SingleBlockCallbackFunction</code>) oder Port-Aufruf über den fehlgeschlagenen Blockzugriff.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Wiederherstellungseinleitung – Step (4) [Recovery Initiator]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>NvM</code> agiert als <em>Recovery Initiator</em>:</li>\n<li><strong>Automatische NvM-Recovery:</strong> Wenn <code>NvMBlockUseCrc</code> oder Redundanz (<code>NVM_BLOCK_REDUNDANT</code>) konfiguriert ist, wird auf die redundante Kopie zugegriffen oder ROM-Default-Daten (<code>NvMRomBlockNum</code> / <code>NvMRomBlockDataAddress</code>) werden in den RAM-Mirror geladen.</li>\n<li><strong>Physischer Recovery-Pfad:</strong> Der <code>NvM</code> triggert einen Schreib-/Reparaturauftrag über <code>MemIf</code> und <code>Fee</code> an den <code>Int. Flash Driver</code> (<code>Fls</code>), um den Block neu zu allozieren, verwaiste Sektoren zu bereinigen oder Defaults persistent einzubrennen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Applikationsgesteuerte Wiederherstellung – Step (5) [Polling / Command]:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Alternativ oder ergänzend reagiert die Applikation auf die Notifikation aus Schritt (3) und fordert explizit eine Wiederherstellung an (z. B. via <code>NvM_RestoreBlockDefaults()</code> oder explizites <code>NvM_WriteBlock()</code> mit synthetisierten Ersatzwerten über die RTE).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>NvM-Konfiguration (<code>NvMBlockDescriptor</code>):</strong></li>\n<li>Für kritische Blöcke ist <code>NvMBlockManagementType = NVM_BLOCK_REDUNDANT</code> vorzusehen, damit der <code>NvM</code> bei Konsistenzfehlern der <code>Fee</code> transparent auf Kopie 2 umschalten kann, bevor ein <code>DEM</code>-Fehler verriegelt wird.</li>\n<li><code>NvMRomBlockDataAddress</code> / <code>NvMRomBlockNum</code> konfigurieren, um deterministisches Laden von Defaultwerten bei <code>MEMIF_BLOCK_INCONSISTENT</code> ohne Blockieren der Applikation sicherzustellen.</li>\n<li>Zuweisung von <code>NvMInitBlockCallback</code> und <code>NvMSingleBlockCallbackFunction</code> zur Benachrichtigung der SWC bei Read-All- bzw. Single-Block-Fehlern.</li>\n<li><strong>Fee/Fls-Treiberrestriktionen:</strong></li>\n<li><code>Fee</code>: Muss atomare Sektorwechsel unterstützen. Die Erkennung eines ungültigen Blocks darf nicht zu Endlosschleifen im internen Garbage-Collection-Mechanismus führen.</li>\n<li>Das Polling-Intervall des <code>NvM</code> (<code>NvM_MainFunction</code>) muss auf die Zykluszeit von <code>Fee_MainFunction</code> und <code>Fls_MainFunction</code> abgestimmt sein, um Latenzen bei der Fehlererkennung zu minimieren.</li>\n<li><strong>Dem-Integration:</strong></li>\n<li>Standardmäßig qualifiziert der <code>NvM</code> Fehler erst nach Erschöpfung konfigurierter Wiederholversuche (<code>NvMMaxNumOfReadRetries</code>). Entwickler müssen sicherstellen, dass nicht jeder transiente Flash-Lesefehler sofort zu einem verfrühten DTC-Eintrag führt.</li>\n<li><strong>ASIL- / Multicore-Kontext:</strong></li>\n<li>Liegt die aufrufende SWC in einer anderen Partition/Core als der <code>NvM</code>, muss die Notifikation über RTE-Inter-Partition-Queues abgesichert sein. Puffer für Default-Werte dürfen im Fehlerfall nicht durch asynchrones Schreiben korrumpiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-0a318a0e65a6cb47", "to": "FIG-aaf1860826f0e81b", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-aaf1860826f0e81b", "to": "FIG-c67ea0e6be9988a9", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c67ea0e6be9988a9", "to": "FIG-5d49904050010c6f", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5d49904050010c6f", "to": "FIG-bfcf7b5cc8f0468a", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bfcf7b5cc8f0468a", "to": "FIG-d61f76a6abda6872", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
